  document.addEventListener('pointerdown',e=>{if(!gridMenu.hidden&&!e.target.closest('#grid-menu,.row-name,.col-name'))closeMenu();},true);
  gridMenu.addEventListener('keydown',e=>{const list=all('.grid-menu-item',gridMenu),i=list.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();closeMenu(true);}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();list[(i+(e.key==='ArrowDown'?1:-1)+list.length)%list.length]?.focus();}});
  stage.addEventListener('wheel',()=>closeMenu(),{passive:true});addEventListener('resize',()=>closeMenu());

  /* ---------- room templates ----------
     Default (chốt 16/11/2026): 4 ghế · lối đi giữa · 4 ghế; the last two rows are all couple seats (two pairs per side). */
  const templateDialog=one('#template-dialog');
  function templateSeats(rows,side,coupleRows,aisle,vip){const width=aisle?side*2+1:side*2,range=(from,n)=>Array.from({length:n},(_,i)=>from+i),segments=aisle?[range(1,side),range(side+2,side)]:[range(1,width)],plain=rows-coupleRows,vipFrom=Math.floor(plain/3),vipTo=plain-Math.floor(plain/3),list=[];
    for(let r=0;r<rows;r++){const row=rowChar(r),couple=r>=plain,type=vip&&plain>=3&&r>=vipFrom&&r<vipTo?'VIP':'STANDARD';let n=0;segments.forEach((segment,k)=>segment.forEach((p,i)=>{n++;const paired=couple&&(i%2===0?i+1<segment.length:true);list.push({label:row+n,rowLabel:row,position:p,type:paired?'COUPLE':type,coupleGroup:paired?row+'-'+k+'-'+Math.floor(i/2):'',active:true});}));}
    return {list,width};}
  function templateInput(){const rows=Number(value('template-rows')),side=Number(value('template-side')),coupleRows=Number(value('template-couple-rows')),aisle=one('#template-aisle').checked;if(!Number.isInteger(rows)||rows<2||rows>MAX_ROWS)throw new Error('Chọn từ 2 đến 20 hàng (A–T).');if(!Number.isInteger(side)||side<1||(aisle?side*2+1:side*2)>MAX_COLS)throw new Error(`Ghế mỗi bên từ 1 đến ${Math.floor((MAX_COLS-1)/2)}.`);if(!Number.isInteger(coupleRows)||coupleRows<0||coupleRows>2||coupleRows>=rows)throw new Error('Hàng ghế đôi từ 0 đến 2 và ít hơn tổng số hàng.');return {...templateSeats(rows,side,coupleRows,aisle,one('#template-vip').checked),rows};}
  function templatePreview(){const error=one('#template-error');try{const {list}=templateInput(),count=t=>list.filter(s=>s.type===t).length;one('#template-preview').textContent=`Sẽ tạo ${list.length} ghế: ${count('STANDARD')} ghế thường, ${count('VIP')} VIP, ${count('COUPLE')/2} cặp ghế đôi.`;error.hidden=true;}catch(e){error.textContent=e.message;error.hidden=false;one('#template-preview').textContent='';}all('.template-preset',templateDialog).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.rows===value('template-rows')&&b.dataset.side===value('template-side'))));}
  all('.template-preset',templateDialog).forEach(b=>b.addEventListener('click',()=>{one('#template-rows').value=b.dataset.rows;one('#template-side').value=b.dataset.side;templatePreview();}));
  templateDialog.addEventListener('input',templatePreview);templateDialog.addEventListener('change',templatePreview);
  function openTemplate(){if(busy||!isNew)return note('Mẫu phòng chỉ dùng khi phòng chưa lưu ghế nào.');templatePreview();templateDialog.showModal();one('#template-apply').focus();}
  one('#template-open').addEventListener('click',openTemplate);one('#canvas-template').addEventListener('click',openTemplate);one('#template-cancel').addEventListener('click',()=>templateDialog.close());
  function useTemplate({list,width,rows}){const before=snapshot();seats=list;deletes.clear();selected=[];seatDirty=false;one('#seat-editor').hidden=true;extent={rows,cols:width};fitting=true;commit(before);note('Đã dựng sơ đồ từ mẫu (chưa lưu). Bấm chữ hàng hoặc số cột để chèn, xóa, đổi loại; xong bấm Lưu sơ đồ.');}
  one('#template-apply').addEventListener('click',()=>{try{const t=templateInput();templateDialog.close();useTemplate(t);}catch(e){one('#template-error').textContent=e.message;one('#template-error').hidden=false;}});
  // A room just created from the "Thêm phòng" pop-up arrives with ?template=<rows>: build the default layout right away.
  function autoTemplate(){const url=new URL(location.href);if(!url.searchParams.has('template'))return;const rows=Number(url.searchParams.get('template'));url.searchParams.delete('template');history.replaceState(null,'',url);if(!isNew||busy||!Number.isInteger(rows)||rows<2||rows>MAX_ROWS)return;useTemplate({...templateSeats(rows,4,2,true,false),rows});}

  /* ---------- rendering ---------- */
  function seatButton(s,index,state,offset=1){const button=el('button',s.label,'seat '+s.type.toLowerCase()+' '+state.toLowerCase());button.type='button';button.dataset.index=index;button.dataset.row=s.rowLabel;button.dataset.pos=s.position;button.style.gridColumn=String(s.position+offset);button.title=s.label+' · '+types[s.type]+' · '+states[state];button.setAttribute('aria-label',button.title);return button;}
  function markPairs(holder,rows){for(const button of all('.seat.couple',holder)){const s=rows[Number(button.dataset.index)],mate=rows.find(p=>p!==s&&p.type==='COUPLE'&&p.coupleGroup===s.coupleGroup);if(mate&&mate.rowLabel===s.rowLabel&&Math.abs(mate.position-s.position)===1)button.classList.add(mate.position>s.position?'pair-first':'pair-last');else button.classList.add('pair-broken');}}
  // Grid (16/11/2026): label · left "+" · seats · right "+". Hovering a row shows "+" at both ends (add a seat to that row)
  // and "+" on its top edge (insert a row above); the column numbers carry "+" on their left edge (insert a column) and
  // "+" at both ends of the header adds a whole column; "+ Thêm hàng" under the last row appends a row.
  function handle(text,cls,title,data){const b=el('button',text,'grid-add '+cls);b.type='button';b.title=title;b.setAttribute('aria-label',title);Object.assign(b.dataset,data);b.tabIndex=-1;return b;}
  function drawLayout(){const focused=document.activeElement?.closest?.('#setup-seat-map [data-pos]'),focusKey=focused&&focused.dataset.row+':'+focused.dataset.pos,lookup=new Map(seats.map((s,i)=>[s.rowLabel+':'+s.position,i])),fragment=document.createDocumentFragment(),flagged=new Set(issues().map(x=>x.index)),columns=`32px 24px repeat(${extent.cols},44px) 24px`,last=extent.cols+3;let first=true;
    if(extent.rows&&extent.cols){const head=el('div',undefined,'seat-row col-head');head.style.gridTemplateColumns=columns;head.append(el('span','','col-corner'));const left=handle('+','add-col-edge','Thêm một cột ở mép trái sơ đồ',{add:'col-start'});left.style.gridColumn='2';head.append(left);
      for(let p=1;p<=extent.cols;p++){const b=el('button',String(p),'col-name');b.type='button';b.dataset.col=p;b.style.gridColumn=String(p+2);b.style.gridRow='1';b.title='Cột '+p+': chèn, xóa hoặc biến thành lối đi';b.setAttribute('aria-label',b.title);b.setAttribute('aria-haspopup','menu');head.append(b);if(p>1){const ins=handle('+','ins-col','Chèn một cột trước cột '+p,{add:'col-before',col:p});ins.style.gridColumn=String(p+2);ins.style.gridRow='1';head.append(ins);}}
      const right=handle('+','add-col-edge','Thêm một cột ở mép phải sơ đồ',{add:'col-end'});right.style.gridColumn=String(last);head.append(right);fragment.append(head);}
    for(let r=0;r<extent.rows;r++){const row=rowChar(r),line=el('div',undefined,'seat-row');line.style.gridTemplateColumns=columns;const name=el('button',row,'row-name');name.type='button';name.dataset.row=row;name.style.gridColumn='1';name.title='Hàng '+row+': đổi loại cả hàng, chèn hoặc xóa';name.setAttribute('aria-haspopup','menu');name.setAttribute('aria-label',name.title);line.append(name);
      if(r>0){const ins=handle('+','ins-row','Chèn một hàng trên hàng '+row+' (chép ghế của hàng này)',{add:'row-before',row:r});ins.style.gridColumn='1';ins.style.gridRow='1';line.append(ins);}
      const addLeft=handle('+','row-add','Thêm ghế vào đầu hàng '+row,{add:'seat',row,side:'left'});addLeft.style.gridColumn='2';line.append(addLeft);
      for(let p=1;p<=extent.cols;p++){const index=lookup.get(row+':'+p);let button;if(index===undefined){button=el('button','','seat-cell');button.type='button';button.dataset.row=row;button.dataset.pos=p;button.style.gridColumn=String(p+2);button.setAttribute('aria-label','Ô trống '+row+p);}else{const s=seats[index];button=seatButton(s,index,s.active?'AVAILABLE':'MAINTENANCE',2);button.classList.toggle('selected',selected.includes(index));button.classList.toggle('has-issue',flagged.has(index));}button.tabIndex=(focusKey?focusKey===row+':'+p:first)?0:-1;first=false;line.append(button);}
      const addRight=handle('+','row-add','Thêm ghế vào cuối hàng '+row,{add:'seat',row,side:'right'});addRight.style.gridColumn=String(last);line.append(addRight);fragment.append(line);}
    if(extent.rows&&extent.cols){const foot=el('div',undefined,'seat-row row-foot');foot.style.gridTemplateColumns=columns;const add=handle('+ Thêm hàng','add-row-end','Thêm một hàng dưới cùng (chép ghế của hàng '+rowChar(extent.rows-1)+')',{add:'row-end'});add.style.gridColumn=`3 / ${last}`;add.tabIndex=0;foot.append(add);fragment.append(foot);}
    map.replaceChildren(fragment);markPairs(map,seats);if(focusKey)cellButton(map,...focusKey.split(':'))?.focus({preventScroll:true});}
  // One seat (two for a couple row) at the start or end of a row; type follows the seat at that end. Extends the grid when needed.
  function addSeat(row,side){if(!editable())return;const inRow=seats.filter(s=>s.rowLabel===row).sort((a,b)=>a.position-b.position),end=side==='left'?inRow[0]:inRow.at(-1),couple=end?.type==='COUPLE',n=couple?2:1,type=end?end.type:tool==='VIP'||tool==='COUPLE'?tool:'STANDARD';
    let from=end?(side==='left'?end.position-n:end.position+1):side==='left'?1:Math.max(1,extent.cols-n+1);const shift=Math.max(0,1-from),to=from+n-1+shift,grow=Math.max(to,extent.cols)-extent.cols+shift;if(extent.cols+grow>MAX_COLS)return note(`Tối đa ${MAX_COLS} cột.`);if(seats.length+n>MAX_SEATS)return note(`Phòng đã đủ ${MAX_SEATS} ghế.`);
    const before=snapshot();if(shift){for(const s of seats)s.position+=shift;from+=shift;}extent.cols=Math.max(extent.cols+shift,from+n-1);const group=type==='COUPLE'?row+'-'+crypto.randomUUID():'';for(let p=from;p<from+n;p++)createSeat(row,p,type,group);renumberAll();commit(before);note(`Đã thêm ${n===2?'một cặp ghế đôi':'một ghế'} vào ${side==='left'?'đầu':'cuối'} hàng ${row}.`);}
  function onHandle(b){const d=b.dataset;if(d.add==='seat')return addSeat(d.row,d.side);if(d.add==='row-before')return insertRow(Number(d.row),Number(d.row));if(d.add==='row-end')return insertRow(extent.rows,extent.rows-1);if(d.add==='col-before')return insertCol(Number(d.col),Number(d.col)-1);if(d.add==='col-start')return insertCol(1,1);if(d.add==='col-end')return insertCol(extent.cols+1,extent.cols);}
  function drawInventory(){const groups=new Map();inventoryRows.forEach((s,index)=>{if(!groups.has(s.rowLabel))groups.set(s.rowLabel,[]);groups.get(s.rowLabel).push({s,index});});const fragment=document.createDocumentFragment(),columns=Math.max(1,...inventoryRows.map(s=>s.position));let first=true;for(const [name,group] of [...groups].sort(([a],[b])=>a.localeCompare(b))){const line=el('div',undefined,'seat-row');line.style.gridTemplateColumns=`32px repeat(${columns},44px)`;line.append(el('span',name,'row-name'));for(const {s,index} of group.sort((a,b)=>a.s.position-b.s.position)){const button=seatButton(s,index,s.state);button.tabIndex=first?0:-1;first=false;button.addEventListener('click',()=>{all('[data-pos]',inventoryMap).forEach(b=>b.tabIndex=-1);button.tabIndex=0;showOrder(s);});line.append(button);}fragment.append(line);}inventoryMap.replaceChildren(fragment);markPairs(inventoryMap,inventoryRows);updateCounts();if(fitting)requestAnimationFrame(()=>fit());}
